/**
 * Product database keyed by barcode (UPC/EAN).
 * MANUAL_PRODUCTS: hand-curated entries — always take priority over generated data.
 * Curated for the Healthy Choices target demographic:
 *   - Health-conscious young adults (20s–30s) who read labels
 *   - Budget-aware moms shopping for their families at Walmart/Target/Kroger
 * Selection criteria: high scan frequency + high educational delta (products that
 * look one way but have surprising ingredient profiles).
 */
let generatedRaw = null;
try { generatedRaw = require('./products_generated.json'); } catch (_) {}

const _generated = {};
if (generatedRaw && Array.isArray(generatedRaw.products)) {
  for (const p of generatedRaw.products) {
    if (p.barcode) _generated[String(p.barcode)] = p;
  }
}

